// src/js/main.js
// Navigation
function showSection() {
  const hash = window.location.hash || '#home';
  document.querySelectorAll('section').forEach(sec => sec.classList.remove('active'));
  const target = document.querySelector(hash);
  if (target) target.classList.add('active');
}

window.addEventListener('hashchange', showSection);
showSection(); // run on load

// Card Sets Logic
const openFormBtn = document.getElementById('openFormBtn');
const setForm = document.getElementById('setForm');
const createSetBtn = document.getElementById('createSetBtn');
const cancelBtn = document.getElementById('cancelBtn');
const setTitleInput = document.getElementById('setTitleInput');
const setsList = document.getElementById('setsList');

openFormBtn?.addEventListener('click', () => {
  setForm.classList.remove('form-hidden');
});

const hideForm = () => {
  setForm.classList.add('form-hidden');
  setTitleInput.value = '';
};

cancelBtn?.addEventListener('click', hideForm);

createSetBtn?.addEventListener('click', () => {
  const title = setTitleInput.value.trim();
  if (!title) return;

  const item = document.createElement('div');
  item.textContent = `Set: ${title}`;
  item.addEventListener('click', () => alert(`Opening set: ${title}`));
  setsList.prepend(item);

  hideForm();
});

// Expose shuffle globally so Mocha tests can import it easily
window.shuffle = function shuffle(array) {
  return [...array].sort(() => Math.random() - 0.5);
};